Baseline confirmed: 92 green. Now create api/src/banco.js.

Design per plan:
- `criarBanco(opcoes)` — opens better-sqlite3 Database. In MODO_TESTE=1 → ':memory:'. Otherwise file at opcoes.arquivoBanco || process.env.DB_ARQUIVO || 'semana.db'. Actually let me allow an options param for the optional persistence test later. Signature: `criarBanco({ arquivoBanco } = {})`.
- Schema create + seed salas/usuarios (INSERT OR IGNORE).
- Prepared statements created and exposed.

Let me design the module to expose a repository object with functions, and the app uses it. Keep it simple:

```js
const Database = require('better-sqlite3');

const SALAS_INICIAIS = [...];
const USUARIOS_INICIAIS = [...];

function montarAtividade(linha) {
  if (!linha) return null;
  return {
    id: linha.id,
    titulo: linha.titulo,
    tipo: linha.tipo,
    salaId: linha.salaId,
    vagas: linha.vagas,
    cargaHorariaMinutos: linha.cargaHorariaMinutos,
    cancelada: linha.cancelada === 1,
    encontros: JSON.parse(linha.encontros)
  };
}

function criarBanco(opcoes = {}) {
  const ehTeste = process.env.MODO_TESTE === '1';
  const arquivo = ehTeste ? ':memory:' : (opcoes.arquivoBanco || process.env.DB_ARQUIVO || 'semana.db');
  const db = new Database(arquivo);
  db.pragma('journal_mode = WAL'); // maybe skip; for memory it's fine? WAL on memory throws? Actually WAL unsupported for :memory:. Let me not set WAL, or set only for file. Skip pragma to stay safe.
  db.exec(`CREATE TABLE IF NOT EXISTS ...`);

  const inserirSala = db.prepare('INSERT OR IGNORE INTO salas (id, nome, capacidade) VALUES (?, ?, ?)');
  const inserirUsuario = db.prepare('INSERT OR IGNORE INTO usuarios (id, papel) VALUES (?, ?)');

  const seed = db.transaction(() => {
    for (const sala of SALAS_INICIAIS) inserirSala.run(sala.id, sala.nome, sala.capacidade);
    for (const usuario of USUARIOS_INICIAIS) inserirUsuario.run(usuario.id, usuario.papel);
  });
  seed();

  const stmtInsertAtividade = db.prepare(`INSERT INTO atividades (id, titulo, tipo, salaId, vagas, cargaHorariaMinutos, cancelada, encontros) VALUES (@id, @titulo, @tipo, @salaId, @vagas, @cargaHorariaMinutos, @cancelada, @encontros)`);
  const stmtObterAtividade = db.prepare('SELECT * FROM atividades WHERE id = ?');
  const stmtListarAtividades = db.prepare('SELECT * FROM atividades');
  const stmtObterSala = db.prepare('SELECT id, nome, capacidade FROM salas WHERE id = ?');
  const stmtListarSalas = db.prepare('SELECT id, nome, capacidade FROM salas');
  const stmtObterUsuario = db.prepare('SELECT id, papel FROM usuarios WHERE id = ?');
  const stmtApagarAtividades = db.prepare('DELETE FROM atividades');
  const stmtAtualizarTitulo = db.prepare('UPDATE atividades SET titulo = ? WHERE id = ?');
  const stmtAtualizarVagas = db.prepare('UPDATE atividades SET vagas = ? WHERE id = ?');
  const stmtAtualizarCancelada = db.prepare('UPDATE atividades SET cancelada = ? WHERE id = ?');

  return {
    obterSala(id) { const linha = stmtObterSala.get(id); return linha || null; },
    listarSalas() { return stmtListarSalas.all(); },
    obterUsuario(id) { const linha = stmtObterUsuario.get(id); return linha || null; },
    obterAtividade(id) { return montarAtividade(stmtObterAtividade.get(id)); },
    listarAtividades() { return stmtListarAtividades.all().map(montarAtividade); },
    inserirAtividade(atividade) {
      stmtInsertAtividade.run({
        id: atividade.id,
        titulo: atividade.titulo,
        tipo: atividade.tipo,
        salaId: atividade.salaId,
        vagas: atividade.vagas,
        cargaHorariaMinutos: atividade.cargaHorariaMinutos,
        cancelada: atividade.cancelada ? 1 : 0,
        encontros: JSON.stringify(atividade.encontros)
      });
    },
    atualizarTitulo(id, titulo) { stmtAtualizarTitulo.run(titulo, id); },
    atualizarVagas(id, vagas) { stmtAtualizarVagas.run(vagas, id); },
    atualizarCancelada(id) { stmtAtualizarCancelada.run(1, id); },
    recarregarDadosIniciais() {
      const resetar = db.transaction(() => {
        stmtApagarAtividades.run();
        for (const sala of SALAS_INICIAIS) inserirSala.run(...);
        for (const usuario of USUARIOS_INICIAIS) inserirUsuario.run(...);
      });
      resetar();
    },
    fechar() { db.close(); }
  };
}

module.exports = { criarBanco };
```

Where do SALAS_INICIAIS and USUARIOS_INICIAIS come from? Currently they're defined in app.js. To avoid duplication, move them into banco.js and export? Or keep in app.js and pass to banco? Minimal churn: move the arrays to banco.js (the seed data), and app.js uses `banco` for salas/usuarios. app.js currently defines SALAS_INICIAIS and USUARIOS_INICIAIS and carregarSalas/carregarUsuarios. Those get deleted from app.js. The contract data: keep in banco.js only.

